package com.nutribite.ai.tracking.repository; import com.nutribite.ai.model.User; import com.nutribite.ai.tracking.entity.WaterLog; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.time.*; import java.util.*;
public interface WaterLogRepository extends JpaRepository<WaterLog,Long>{ List<WaterLog> findByUserAndLoggedAtBetweenOrderByLoggedAtDesc(User user,LocalDateTime start,LocalDateTime end); @Query("select coalesce(sum(w.amountLiters),0) from WaterLog w where w.user=:user and w.loggedAt>=:start and w.loggedAt<:end") Double sumBetween(@Param("user") User user,@Param("start") LocalDateTime start,@Param("end") LocalDateTime end); Optional<WaterLog> findByIdAndUser(Long id,User user);}
